'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { identifyHub, modelLabel, validateCode, encodeCommand } = require('../lib/RMCloudModels');
const { BroadlinkCloud } = require('../lib/BroadlinkCloud');

// Independent integration fixture, not generated by encodeCommand:
// https://github.com/home-assistant/core/blob/dev/tests/components/broadlink/test_remote.py
const IR = Buffer.from('JgBGAJKVETkRORA6ERQRFBEUERQRFBE5ETkQOhAVEBUQFREUEBUQOhEUERQRORE5EBURFBA6EBUQOhE5EBUQFRA6EDoRFBEADQUAAA==', 'base64').toString('hex');
const RF = 'b2000600111122223333'; // Same upstream test file; synthetic RF waveform.
const RF315 = 'd70004000b210d21';
// Synthetic complete 0xb1 packet with the carrier/header documented in
// broadlink-async remote.py; no claim of a full hardware capture.
const RF4 = 'b1c00800009f06000b210d21';
const session = { provider: 'broadlink_eu', userId: 'uid', loginSession: 'session', familyId: 'home' };
const key = '00112233445566778899aabbccddeeff';
const cookie = { terminalid: 0x12345678, aeskey: key };
function pid(type) { const value = Buffer.alloc(16); value.writeUInt16LE(type, 12); return value.toString('hex'); }
function hub(type) { return { endpointId: 'hub', productId: pid(type), mac: 'aa:bb:cc:dd:ee:ff', devicetypeFlag: 1, cookie: Buffer.from(JSON.stringify(cookie)).toString('base64') }; }
function ack(directive) { return { event: { header: { namespace: 'DNA.TransmissionControl', name: 'Response', interfaceVersion: '2', messageId: directive.header.messageId }, endpoint: { endpointId: directive.endpoint.endpointId }, payload: { data: 'AgAAAAAAAAAAAAAAAAAAAA==' } } }; }

test('only explicit allowlisted RM3 Mini and RM4 types/PIDs identify a hub', () => {
  const groups = {
    rm3_mini: [0x2737, 0x278f, 0x27c2, 0x5f36],
    rm4_mini: [0x51da, 0x5209, 0x520c, 0x520d, 0x5211, 0x5212, 0x5216, 0x521c, 0x6070, 0x610e, 0x610f, 0x62bc, 0x62be, 0x6364, 0x648d, 0x6539, 0x653a],
    rm4_pro: [0x520b, 0x5213, 0x5218, 0x6026, 0x6184, 0x61a2, 0x649b, 0x653c],
  };
  for (const [model, types] of Object.entries(groups)) for (const devtype of types) {
    const expected = { model, devtype };
    assert.deepEqual(identifyHub({ devtype }), expected);
    assert.deepEqual(identifyHub({ productId: pid(devtype).toUpperCase() }), expected);
    assert.deepEqual(identifyHub({ cookie: { Pid: pid(devtype) } }), expected);
    assert.deepEqual(identifyHub({ cookie: Buffer.from(JSON.stringify({ device: { pid: pid(devtype), devtype } })).toString('base64') }), expected);
  }
  assert.equal(modelLabel('rm3_mini'), 'RM3 Mini');
  assert.equal(modelLabel('rm4_mini'), 'RM4 Mini');
  assert.equal(modelLabel('rm4_pro'), 'RM4 Pro');
  assert.equal(modelLabel('__proto__'), '');
});

test('unknown, ambiguous, malformed or contradictory identity fails closed', () => {
  for (const endpoint of [null, [], {}, { name: 'RM4 Pro' }, { model: 'rm4_pro' }, { devtype: '0x520b' }, { devtype: 0x2712 }, { devtype: 0x5224 }, { devtype: 0xaf8b }, { productId: pid(0xaf8b) }, { productId: pid(0x5224) }, { productId: '520b' }, { productId: '000000000000000000000000520b0000' }, { devtype: 0x520b, productId: pid(0x51da) }, { devtype: 0x520b, cookie: { devtype: 0x5213 } }, { devtype: 0x2737, cookie: { device: { pid: pid(0x5f36) } } }, { devtype: 0x520b, cookie: 'invalid' }, { devtype: 0x520b, cookie: { device: [] } }, { devtype: 0x520b, model: 'rm4_mini' }]) {
    assert.equal(identifyHub(endpoint), null, JSON.stringify(endpoint));
  }
});

test('validates real-shaped IR and independent synthetic RF without converting bytes', () => {
  for (const model of ['rm3_mini', 'rm4_mini', 'rm4_pro']) assert.equal(validateCode(model, IR), true);
  for (const packet of [RF, RF315, RF4]) {
    assert.equal(validateCode('rm4_pro', packet), true);
    assert.equal(validateCode('rm3_mini', packet), false);
    assert.equal(validateCode('rm4_mini', packet), false);
  }
  assert.equal(validateCode('rm4_mini', '260006001000012492200d050000'), true);
  for (const packet of ['', 'aa', 'zz00040011223344', '260000001122', '260010001122', '26000300110001', '2600040011000000', '26000300112233', '260002001122ff', 'b1c00c00009f06000b210d21', 'b1000800009f06000b210d21', 'b1c00800000000000b210d21', '020000002600040011223344', '260002001122' + '00'.repeat(17)]) assert.equal(validateCode('rm4_pro', packet), false, packet);
  assert.equal(validateCode('unknown', IR), false);
  assert.equal(validateCode('rm4_pro', '26'.repeat(65532)), false);
});

test('command framing preserves classic Mini and length-prefixes Red Bean/RM4', () => {
  const raw = '2600040011223344';
  assert.equal(encodeCommand({ devtype: 0x2737 }, raw).toString('hex'), '020000002600040011223344');
  for (const devtype of [0x5f36, 0x51da, 0x520b]) assert.equal(encodeCommand({ devtype }, raw).toString('hex'), '0c00020000002600040011223344');
  assert.equal(encodeCommand({ devtype: 0x520b }, RF4).toString('hex'), '100002000000b1c00800009f06000b210d21');
  assert.throws(() => encodeCommand({ devtype: 0xaf8b }, raw), /hub identity/);
  assert.throws(() => encodeCommand({ devtype: 0x51da }, RF), /Invalid saved RM code/);
});

test('EU sendRMCode binds the endpoint, model-correct bytes and canonical credentials', async () => {
  let count = 0;
  for (const [type, packet, prefix] of [[0x2737, IR, '02000000'], [0x5f36, '2600040011223344', '0c0002000000'], [0x51da, '2600040011223344', '0c0002000000'], [0x520b, RF4, '100002000000']]) {
    const endpoint = hub(type);
    if (type === 0x5f36) endpoint.cookie = { device: { id: cookie.terminalid, key } };
    const cloud = new BroadlinkCloud(session, { request: async (url, req) => {
      count++;
      assert.match(url, /^https:\/\/app-service-deu-6dc239d5\.ibroadlink\.com\/device\/control\/v2\/sdkcontrol\?license=/);
      assert.equal(req.timeoutMs, 10000);
      assert.equal(req.headers.familyid, 'home');
      const d = JSON.parse(req.body).directive;
      assert.equal(d.header.name, 'commonControl');
      assert.equal(d.payload.data, Buffer.from(prefix + packet, 'hex').toString('base64'));
      assert.equal(d.payload.notpadding, 0);
      assert.equal(d.endpoint.endpointId, 'hub');
      assert.deepEqual(JSON.parse(Buffer.from(d.endpoint.devicePairedInfo.cookie, 'base64')), { device: { id: 0x12345678, key, aeskey: key, did: 'hub', pid: pid(type), mac: endpoint.mac } });
      return ack(d);
    } });
    await cloud.sendRMCode(endpoint, packet);
  }
  assert.equal(count, 4);
});

test('invalid inputs never reach the cloud transport', async () => {
  let count = 0;
  const cloud = new BroadlinkCloud(session, { request: async () => { count++; } });
  for (const [endpoint, packet] of [[hub(0xaf8b), IR], [hub(0x5224), IR], [hub(0x51da), RF], [hub(0x520b), '260010001122'], [{ ...hub(0x520b), endpointId: '' }, IR], [{ ...hub(0x520b), cookie: {} }, IR], [{ ...hub(0x520b), cookie: { ...cookie, id: 2 } }, IR], [{ ...hub(0x520b), cookie: { ...cookie, key: 'aa'.repeat(16) } }, IR], [{ ...hub(0x520b), devtype: 0x51da }, IR]]) await assert.rejects(cloud.sendRMCode(endpoint, packet));
  assert.equal(count, 0);
});

test('only the known EU ack is accepted; reply binding and rejects cause no retry', async () => {
  const mutations = [
    response => { response.event.header.messageId = 'unrelated'; },
    response => { response.event.endpoint.endpointId = 'other'; },
    response => { response.event.header.namespace = 'DNA.Power'; },
    response => { response.event.header.name = 'Other'; },
    response => { response.event.header.interfaceVersion = '3'; },
    response => { response.event.payload.status = -1; },
    response => { response.event.payload.data = Buffer.from('040000000000', 'hex').toString('base64'); },
    response => { response.event.payload.data = Buffer.from('01000000', 'hex').toString('base64'); },
    response => { response.event.payload.data = Buffer.alloc(16).toString('base64'); },
    response => { response.status = -1; },
    response => { response.status = -1012; },
  ];
  for (const mutate of mutations) {
    let count = 0;
    const cloud = new BroadlinkCloud(session, { request: async (url, req) => { count++; const response = ack(JSON.parse(req.body).directive); mutate(response); return response; } });
    await assert.rejects(cloud.sendRMCode(hub(0x520b), RF));
    assert.equal(count, 1);
  }
});

test('timeout, authentication and secret-bearing transport failures are bounded and safe', async () => {
  for (const error of [Object.assign(new Error('secret'), { code: 'AUTH_REQUIRED', httpStatus: 401 }), new Error('secret request token')]) {
    let count = 0;
    const cloud = new BroadlinkCloud(session, { request: async () => { count++; throw error; } });
    await assert.rejects(cloud.sendRMCode(hub(0x520b), RF), result => !result.message.includes('secret') && result.code === error.code);
    assert.equal(count, 1);
  }
  let count = 0;
  const cloud = new BroadlinkCloud(session, { timeoutMs: 5, request: () => { count++; return new Promise(() => {}); } });
  await assert.rejects(cloud.sendRMCode(hub(0x520b), RF), error => error.code === 'TIMEOUT');
  assert.equal(count, 1);
  const invalidTimeout = new BroadlinkCloud(session, { timeoutMs: 10001, request: async () => { count++; } });
  await assert.rejects(invalidTimeout.sendRMCode(hub(0x520b), RF), /Invalid request timeout/);
  assert.equal(count, 1);
  const expired = new BroadlinkCloud(session, { request: async () => ({ status: -1012, msg: 'secret session' }) });
  await assert.rejects(expired.sendRMCode(hub(0x520b), RF), error => error.code === 'AUTH_REQUIRED' && error.remoteStatus === -1012 && !error.message.includes('secret'));
});

test('parallel sends use distinct message IDs and snapshot endpoint binding', async () => {
  const messages = new Set();
  const endpoint = hub(0x520b);
  const cloud = new BroadlinkCloud(session, { request: async (url, req) => {
    const d = JSON.parse(req.body).directive;
    messages.add(d.header.messageId);
    endpoint.endpointId = 'changed-after-send';
    return ack(d);
  } });
  await Promise.all([cloud.sendRMCode(endpoint, RF), cloud.sendRMCode(endpoint, RF)]);
  assert.equal(messages.size, 2);
});
